import graphql from "@graphql-eslint/eslint-plugin";
// the rules that run without a schema or a document set (the others stop ESLint at load)
const free = new Set(["lone-schema-definition", "unique-directive-names", "unique-field-definition-names", "unique-input-field-names", "unique-operation-types", "unique-type-names", "description-style", "input-name", "lone-executable-definition", "naming-convention", "no-anonymous-operations", "no-duplicate-fields", "no-hashtag-description", "no-typename-prefix", "relay-connection-types", "require-deprecation-date", "require-deprecation-reason", "require-nullable-fields-with-oneof", "require-type-pattern-with-oneof", "unique-enum-value-names"].map((n) => `@graphql-eslint/${n}`));
const recommended = { ...graphql.configs["flat/schema-recommended"].rules, ...graphql.configs["flat/operations-recommended"].rules };
const rules = Object.fromEntries(Object.entries(recommended).filter(([n]) => free.has(n)));
export default [{ linterOptions: { noInlineConfig: true }, files: ["**/*.graphql", "**/*.gql"], languageOptions: { parser: graphql.parser }, plugins: { "@graphql-eslint": graphql }, rules }];

import vue from "eslint-plugin-vue";
import tseslint from "typescript-eslint";
export default [...vue.configs["flat/recommended"], { files: ["**/*.vue"], languageOptions: { parserOptions: { parser: tseslint.parser } } }];

import svelte from "eslint-plugin-svelte";
import tseslint from "typescript-eslint";
export default [...svelte.configs["flat/recommended"], { files: ["**/*.svelte"], languageOptions: { parserOptions: { parser: tseslint.parser } } }];

import plugin from "@angular-eslint/eslint-plugin-template";
import parser from "@angular-eslint/template-parser";
const rules = Object.fromEntries(["@angular-eslint/template/alt-text", "@angular-eslint/template/click-events-have-key-events", "@angular-eslint/template/elements-content", "@angular-eslint/template/interactive-supports-focus", "@angular-eslint/template/label-has-associated-control", "@angular-eslint/template/mouse-events-have-key-events", "@angular-eslint/template/no-autofocus", "@angular-eslint/template/no-distracting-elements", "@angular-eslint/template/role-has-required-aria", "@angular-eslint/template/table-scope", "@angular-eslint/template/valid-aria", "@angular-eslint/template/banana-in-box", "@angular-eslint/template/eqeqeq", "@angular-eslint/template/no-negated-async", "@angular-eslint/template/prefer-control-flow"].map((r) => [r, "error"]));
export default [{ files: ["**/*.component.html"], languageOptions: { parser }, plugins: { "@angular-eslint/template": plugin }, rules, linterOptions: { noInlineConfig: true } }];
